def pack_evidence(ranked, budget):
    selected, used = [], 0
    for doc_id, token_count in ranked:
        if token_count <= 0:
            raise ValueError("Token counts must be positive")
        if used + token_count <= budget:
            selected.append(doc_id)
            used += token_count
    return selected

assert pack_evidence([("a", 80), ("b", 90), ("c", 20)], 100) == ["a", "c"]
